query IssueQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    issueOrPullRequest(number: $number) {
      __typename
      ... on Issue {
        id
        number
        title
        body
        state
        stateReason
        author {
          login
        }
        createdAt
        labels(first: 20) {
          totalCount
          nodes {
            name
            color
          }
        }
        assignees(first: 10) {
          totalCount
          nodes {
            login
          }
        }
        milestone {
          number
          title
        }
        comments {
          totalCount
        }
        timelineItems(last: 100, itemTypes: [ISSUE_COMMENT, CLOSED_EVENT, REOPENED_EVENT, CROSS_REFERENCED_EVENT, REFERENCED_EVENT, LABELED_EVENT, UNLABELED_EVENT, ASSIGNED_EVENT, UNASSIGNED_EVENT, MILESTONED_EVENT, DEMILESTONED_EVENT, ADDED_TO_PROJECT_V2_EVENT, REMOVED_FROM_PROJECT_V2_EVENT, PROJECT_V2_ITEM_STATUS_CHANGED_EVENT, RENAMED_TITLE_EVENT, LOCKED_EVENT, UNLOCKED_EVENT, PINNED_EVENT, UNPINNED_EVENT, TRANSFERRED_EVENT, MARKED_AS_DUPLICATE_EVENT, UNMARKED_AS_DUPLICATE_EVENT, SUB_ISSUE_ADDED_EVENT, SUB_ISSUE_REMOVED_EVENT, PARENT_ISSUE_ADDED_EVENT, PARENT_ISSUE_REMOVED_EVENT, ISSUE_TYPE_ADDED_EVENT, ISSUE_TYPE_CHANGED_EVENT, ISSUE_TYPE_REMOVED_EVENT, CONVERTED_TO_DISCUSSION_EVENT]) {
          totalCount
          nodes {
            __typename
            ... on IssueComment {
              id
              fullDatabaseId
              author {
                login
              }
              body
              createdAt
              viewerCanUpdate
              viewerCanDelete
              viewerCanReact
              reactionGroups {
                content
                viewerHasReacted
                reactors {
                  totalCount
                }
              }
            }
            ... on ClosedEvent {
              actor {
                login
              }
              createdAt
              closer {
                __typename
                ... on Commit {
                  oid
                }
                ... on PullRequest {
                  number
                  title
                  __typename
                  ... {
                    isDraft
                    state
                  }
                  repository {
                    nameWithOwner
                  }
                }
              }
              stateReason
            }
            ... on ReopenedEvent {
              actor {
                login
              }
              createdAt
            }
            ... on CrossReferencedEvent {
              actor {
                login
              }
              createdAt
              source {
                __typename
                ... on Issue {
                  number
                  title
                  state
                  stateReason
                  repository {
                    nameWithOwner
                  }
                }
                ... on PullRequest {
                  number
                  title
                  __typename
                  ... {
                    isDraft
                    state
                  }
                  repository {
                    nameWithOwner
                  }
                }
              }
              willCloseTarget
            }
            ... on ReferencedEvent {
              actor {
                login
              }
              createdAt
              commit {
                oid
              }
              commitRepository {
                nameWithOwner
              }
            }
            ... on LabeledEvent {
              actor {
                login
              }
              createdAt
              label {
                name
                color
              }
            }
            ... on UnlabeledEvent {
              actor {
                login
              }
              createdAt
              label {
                name
                color
              }
            }
            ... on AssignedEvent {
              actor {
                login
              }
              createdAt
              assignee {
                __typename
                ... on User {
                  login
                }
                ... on Bot {
                  login
                }
              }
            }
            ... on UnassignedEvent {
              actor {
                login
              }
              createdAt
              assignee {
                __typename
                ... on User {
                  login
                }
                ... on Bot {
                  login
                }
              }
            }
            ... on MilestonedEvent {
              actor {
                login
              }
              createdAt
              milestoneTitle
            }
            ... on DemilestonedEvent {
              actor {
                login
              }
              createdAt
              milestoneTitle
            }
            ... on AddedToProjectV2Event {
              actor {
                login
              }
              createdAt
            }
            ... on RemovedFromProjectV2Event {
              actor {
                login
              }
              createdAt
            }
            ... on ProjectV2ItemStatusChangedEvent {
              actor {
                login
              }
              createdAt
              previousStatus
              status
            }
            ... on RenamedTitleEvent {
              actor {
                login
              }
              createdAt
              previousTitle
              currentTitle
            }
            ... on LockedEvent {
              actor {
                login
              }
              createdAt
              lockReason
            }
            ... on UnlockedEvent {
              actor {
                login
              }
              createdAt
            }
            ... on PinnedEvent {
              actor {
                login
              }
              createdAt
            }
            ... on UnpinnedEvent {
              actor {
                login
              }
              createdAt
            }
            ... on TransferredEvent {
              actor {
                login
              }
              createdAt
              fromRepository {
                nameWithOwner
              }
            }
            ... on MarkedAsDuplicateEvent {
              actor {
                login
              }
              createdAt
              canonical {
                __typename
                ... on Issue {
                  number
                  title
                  state
                  stateReason
                  repository {
                    nameWithOwner
                  }
                }
                ... on PullRequest {
                  number
                  title
                  __typename
                  ... {
                    isDraft
                    state
                  }
                  repository {
                    nameWithOwner
                  }
                }
              }
            }
            ... on UnmarkedAsDuplicateEvent {
              actor {
                login
              }
              createdAt
              canonical {
                __typename
                ... on Issue {
                  number
                  title
                  state
                  stateReason
                  repository {
                    nameWithOwner
                  }
                }
                ... on PullRequest {
                  number
                  title
                  __typename
                  ... {
                    isDraft
                    state
                  }
                  repository {
                    nameWithOwner
                  }
                }
              }
            }
            ... on SubIssueAddedEvent {
              actor {
                login
              }
              createdAt
              subIssue {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
            }
            ... on SubIssueRemovedEvent {
              actor {
                login
              }
              createdAt
              subIssue {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
            }
            ... on ParentIssueAddedEvent {
              actor {
                login
              }
              createdAt
              parent {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
            }
            ... on ParentIssueRemovedEvent {
              actor {
                login
              }
              createdAt
              parent {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
            }
            ... on IssueTypeAddedEvent {
              actor {
                login
              }
              createdAt
              issueType {
                name
              }
            }
            ... on IssueTypeChangedEvent {
              actor {
                login
              }
              createdAt
              issueType {
                name
              }
              prevIssueType {
                name
              }
            }
            ... on IssueTypeRemovedEvent {
              actor {
                login
              }
              createdAt
              issueType {
                name
              }
            }
            ... on ConvertedToDiscussionEvent {
              actor {
                login
              }
              createdAt
            }
          }
        }
        closedByPullRequestsReferences(first: 10, includeClosedPrs: true) {
          totalCount
          nodes {
            number
            title
            __typename
            ... {
              isDraft
              state
            }
            repository {
              nameWithOwner
            }
          }
        }
        linkedBranches(first: 10) {
          totalCount
          nodes {
            ref {
              name
            }
          }
        }
        parent {
          number
          title
          state
          stateReason
          repository {
            nameWithOwner
          }
        }
        subIssues(first: 50) {
          totalCount
          nodes {
            number
            title
            state
            stateReason
            repository {
              nameWithOwner
            }
          }
        }
        subIssuesSummary {
          completed
          total
        }
        issueType {
          name
        }
        repository {
          nameWithOwner
        }
        viewerCanClose
        viewerCanReopen
        viewerCanUpdate
        viewerCanReact
        viewerCanLabel
        viewerCanAssign
        viewerCanSetMilestone
        reactionGroups {
          content
          viewerHasReacted
          reactors {
            totalCount
          }
        }
      }
      ... on PullRequest {
        number
      }
    }
  }
}
